    fun text(lang: String, key: String): String = (if (lang == "ru") ru else en)[key] ?: key

    fun status(lang: String, raw: String): String {
        if (lang != "ru") return raw
        return statuses[raw]
            ?: raw.replace("MiB", "МБ")
                .replace("Receiver rejected upload:", "Получатель отклонил передачу:")
                .replace("Cannot start:", "Не удалось запустить:")
                .replace("Cannot start availability:", "Не удалось включить приём:")
    }
